insert into question_bank_items (id, stage_id, position, question, hint, answer) values (45, 3, 14, 'How do you test a WebSocket or streaming endpoint?', 'It is a conversation over time, not a request/response.', ARRAY['Test the lifecycle: connect and handshake (including auth), send and receive messages in order, and a clean close — plus reconnection and resuming after a dropped connection.', 'Cover the unhappy paths that request/response tests never hit: server closes mid-stream, malformed frames, backpressure when the client is slow, and idle timeouts.', 'For streaming responses (SSE, chunked, or an LLM token stream) assert the chunks arrive incrementally, in order, and that a mid-stream error is surfaced rather than swallowed.']::text[]);
insert into question_bank_stages (id, lang, position, icon, title) values (4, 'en', 3, '🐳', 'Stage 4 — DevOps & CI');
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (46, 4, 0, 'Why run tests in Docker, and what makes a build reproducible?', 'Same image, same result — the point is deleting "works on my machine".', ARRAY['A container pins the OS, runtime, browser and system libraries, so the suite behaves the same on a laptop and on a runner. Browser version drift is one of the top causes of phantom CI failures.', 'Reproducible means pinned: exact base image tags or digests, a committed lockfile, no `latest`, and no network installs at test time.', 'It also buys disposable environments — bring up app, database and fixtures with compose, run, throw it away — so no state leaks between runs.', 'Mention the real gotchas: Chromium needs a larger `/dev/shm` than the 64 MB default, and the image architecture has to match the platform-native binaries your lockfile carries.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (47, 4, 1, 'Walk me through a CI pipeline that runs your tests on every pull request.', 'Walk the stages in order, and say what fails the build.', ARRAY['Trigger on pull request: check out, restore caches, install with a frozen lockfile so CI cannot silently resolve different versions than the developer had.', 'Static gates first because they are cheapest — lint, typecheck, format.', 'Then tests fastest-first: unit, then integration and API, then E2E over the critical journeys. Fail the build on any failure, and publish reports and artifacts (screenshots, video, traces) whether it passed or not.', 'Make it a gate rather than a suggestion: required status checks plus branch protection. Deployment to staging happens on merge, not on the PR.', 'Add a scheduled full run for the slow and flaky-prone tests you deliberately keep off the PR path.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (48, 4, 2, 'How do you speed up a slow suite — parallelism, sharding, test selection?', 'Measure first. You cannot parallelise a suite you have not profiled.', ARRAY['Start with data: which tests dominate the wall clock, and how much of each is setup rather than assertion.', 'Parallelise across workers and shard across machines, balancing shards by historical duration rather than by test count — equal counts do not mean equal time.', 'Cut setup cost: seed through the API instead of the UI, reuse an authenticated session or storage state, and share expensive read-only fixtures.', 'Run a selection on PRs — smoke plus tests affected by the diff — and the full suite nightly. And delete tests that assert nothing: the fastest test is the one you do not run.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (49, 4, 3, 'How do you surface results: reports, trends, and failure screenshots?', 'A failure should say what broke and let you see it, without anyone re-running it.', ARRAY['Publish a report per run — HTML or Allure — with status, duration and history per test, and attach a screenshot, a video and a trace for every failure.', 'Traces matter most: they let you replay the failure with DOM, network and console, instead of reconstructing it from a stack trace.', 'Track trends rather than the last run alone: pass rate, duration and flaky rate over time. One red run is noise; a rising flaky rate is a signal.', 'Push a summary where people already are — a PR comment, a Slack message — and retain artifacts long enough to debug an intermittent failure a week later.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (50, 4, 4, 'How do you handle secrets and environment config in CI?', 'Never in the repo, never in the log, and scoped to the job that needs them.', ARRAY['Keep them in the CI provider’s secret store or a vault, inject them as environment variables at runtime, and keep non-secret config in committed per-environment files.', 'Never commit a secret — and if one lands in git, rotate it. Removing the commit does not un-leak it.', 'Rely on log masking but do not trust it: avoid dumping the environment, and keep secrets out of URLs, where they end up in logs, traces and analytics.', 'Scope and rotate: least-privilege test accounts, separate credentials per environment, short-lived tokens (OIDC) instead of long-lived keys, and no production secrets in a test pipeline.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (51, 4, 5, 'Blue-green vs. canary deployment — where does testing fit each?', 'Both let you verify in production before committing everyone to it.', ARRAY['Blue-green runs two identical environments and flips all traffic at once; you smoke-test the idle (green) environment before the switch, and roll back by flipping back.', 'Canary shifts a small slice of real traffic to the new version and watches error rate, latency and business metrics before widening — testing continues in production, automatically gated on those signals.', 'Both need a fast automated smoke suite and good monitoring as the real gate. Canary gives finer risk control and needs metric-based automation; blue-green gives an instant, clean rollback.']::text[]);